def transform(g):
    H,W=len(g),len(g[0])
    c4=[(r,c) for r in range(H) for c in range(W) if g[r][c]==4]
    c6=[(r,c) for r in range(H) for c in range(W) if g[r][c]==6]
    out=[[0]*W for _ in range(H)]
    if not c4: return out
    r0,r1=min(r for r,c in c4),max(r for r,c in c4)
    k0,k1=min(c for r,c in c4),max(c for r,c in c4)
    for r,c in c4: out[r][c]=4
    if c6:
        r6=(min(r for r,c in c6)+max(r for r,c in c6))/2
        k6=(min(c for r,c in c6)+max(c for r,c in c6))/2
        if k0<=k6<=k1:  # 6 above/below -> vertical flip, adjacent below (or above)
            if r6>r1:
                for r,c in c4:
                    nr=r1+1+(r1-r)
                    if 0<=nr<H: out[nr][c]=4
            else:
                for r,c in c4:
                    nr=r0-1-(r-r0)
                    if 0<=nr<H: out[nr][c]=4
        else:  # side -> horizontal flip, adjacent on side of 6
            w=k1-k0+1
            if k6>k1:  # right
                for r,c in c4:
                    nc=k1+1+(k1-c)
                    if 0<=nc<W: out[r][nc]=4
            else:      # left
                for r,c in c4:
                    nc=k0-1-(c-k0)
                    if 0<=nc<W: out[r][nc]=4
    return out

